<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
use App\Services\AccountabilityService;use App\Services\ExportService;use App\Support\Database;
$db=Database::connection();$tid=(int)$db->query('SELECT id FROM tournaments WHERE deleted_at IS NULL ORDER BY id DESC LIMIT 1')->fetchColumn();if(!$tid)exit(1);$db->beginTransaction();try{$tag='account-'.bin2hex(random_bytes(3));$db->prepare('INSERT INTO news_posts(tournament_id,title,slug,excerpt,body,status,published_at,created_at,updated_at) VALUES(?,?,?,?,?,"published",NOW(),NOW(),NOW())')->execute([$tid,$tag,$tag,'summary','body']);$db->prepare('INSERT INTO galleries(tournament_id,title,description,status,created_at,updated_at) VALUES(?,?,?,"published",NOW(),NOW())')->execute([$tid,$tag,'gallery']);$dash=(new AccountabilityService($db))->dashboard($tid);if(!array_key_exists('teams',$dash)||!array_key_exists('documents',$dash))throw new RuntimeException('Dashboard incomplete');$db->rollBack();$export=new ExportService($db);$job=$export->create($tid,null,'teams');$path=$export->run($job);if(!is_file(dirname(__DIR__).'/storage/'.$path))throw new RuntimeException('CSV absent');$zip=$export->create($tid,null,'zip_documents');$zipPath=$export->run($zip);if(!is_file(dirname(__DIR__).'/storage/'.$zipPath))throw new RuntimeException('ZIP absent');echo "ACCOUNTABILITY_E2E_OK\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
